window.RXA.push(
/* ===== ORTOPEDIA / REUMATOLOGIA ===== */
{n:'Lombalgia aguda mecânica',cid:'M54.5',sp:'Ortopedia',ps:[{v:'EV / IM / VO',i:['Cetoprofeno 100 mg + SF 100 mL EV (ou diclofenaco 75 mg IM / ibuprofeno 600 mg VO) — AINE é 1ª linha','Dipirona 1 g EV/VO','Ciclobenzaprina 5–10 mg VO (relaxante muscular — benefício modesto, sedação); diazepam NÃO é superior ao placebo','Evitar opioides e corticoide sistêmico (sem benefício em lombalgia/ciática — meta-análises)','Sem exame de imagem na lombalgia aguda sem red flags (< 6 semanas) — não melhora desfecho e aumenta intervenções','Red flags: trauma, > 50 a/< 20 a, câncer, febre, perda de peso, imunossupressão, uso de drogas EV, dor noturna/em repouso, déficit neurológico progressivo, retenção/incontinência, anestesia em sela (cauda equina → RM urgente)']}],casa:[{v:'USO ORAL',i:[['Ibuprofeno 600 mg (ou naproxeno 500 mg 12/12 h / diclofenaco 50 mg 8/8 h / cetoprofeno 100 mg 12/12 h)','15 comprimidos','Tomar 1 comprimido de 8/8 h após as refeições por 5 dias (não ultrapassar 7–10 dias)'],['Dipirona 500 mg (ou paracetamol 750 mg — eficácia menor na lombalgia)','20 comprimidos','Tomar 1–2 comprimidos de 6/6 h se dor'],['Ciclobenzaprina 5 mg','7 comprimidos','Tomar 1 comprimido à noite por até 7 dias (sonolência — não dirigir)'],['Omeprazol 20 mg (se > 60 anos, úlcera prévia, AAS/corticoide)','10 cápsulas','Tomar 1 cápsula em jejum enquanto usar o anti-inflamatório'],['Tramadol 50 mg (APENAS resgate, dor intensa não controlada)','10 cápsulas','Tomar 1 cápsula de 8/8 h se dor intensa, por no máximo 3 dias']]}],ori:['MANTER-SE ATIVO: repouso no leito piora a recuperação; caminhar, retomar atividades normais o quanto possível; calor local 20 min 3×/dia','Evolução favorável em 90% em 4–6 semanas; não há "pedra/coluna fora do lugar"; retorno ao trabalho precoce com adaptações','Fisioterapia/exercícios (fortalecimento de core, alongamento), pilates, yoga se > 2–4 semanas; evitar sedentarismo; perder peso; ergonomia','Ciática sem déficit: mesma conduta; 70–80% melhoram em 6–12 semanas; RM se persistir > 6 semanas ou déficit','Acupuntura e manipulação espinhal: benefício pequeno a curto prazo'],al:['Perda de força progressiva na perna/pé caído, dormência em sela, retenção ou incontinência urinária/fecal → PS IMEDIATO (cauda equina)','Febre, dor noturna que não alivia com repouso, perda de peso, história de câncer','Dor que não melhora após 4–6 semanas de tratamento adequado'],ref:'ACP 2017 (Qaseem); NICE NG59 (2016/2020); Lancet Low Back Pain Series 2018; Cochrane 2020 (AINE), 2021 (opioides); Friedman JAMA 2015 (naproxeno ± ciclobenzaprina/oxicodona); Goldberg JAMA 2015 (corticoide na ciática — sem benefício em dor); SBOT/SBR.'},
{n:'Entorse de tornozelo',cid:'S93.4',sp:'Ortopedia',ps:[{v:'VO / IM / LOCAL',i:['Regras de Ottawa: RX apenas se dor na zona maleolar + (dor à palpação da borda posterior/ponta dos maléolos OU base do 5º metatarso OU navicular OU incapacidade de dar 4 passos imediatamente e no PS)','Ibuprofeno 600 mg VO ou cetoprofeno 100 mg EV; dipirona 1 g','Gelo 15–20 min, compressão com bandagem elástica (figura de 8), elevação','Imobilização: tornozeleira/órtese semirrígida (grau I–II) é superior ao gesso/tala rígida (OBLIGATO, Cochrane); tala posterior por até 10 dias somente em grau III/dor intensa com apoio impossível','Muletas por 1–3 dias com carga conforme tolerado; profilaxia de TVP não é rotina']}],casa:[{v:'USO ORAL',i:[['Ibuprofeno 600 mg (ou naproxeno 500 mg 12/12 h)','15 comprimidos','Tomar 1 comprimido de 8/8 h após as refeições por 5 dias'],['Dipirona 500 mg (ou paracetamol 750 mg)','20 comprimidos','Tomar 1 comprimido de 6/6 h se dor']]},{v:'USO TÓPICO',i:[['Diclofenaco dietilamônio 1% gel (ou cetoprofeno 2,5% gel) — eficácia comparável ao oral com menos efeitos GI','1 bisnaga','Aplicar fina camada no tornozelo 3–4×/dia por 7 dias']]}],ori:['PRICE/POLICE nas primeiras 48–72 h: Proteção, Carga Ótima (apoio progressivo conforme dor), Gelo 15–20 min a cada 2–3 h (com pano), Compressão, Elevação acima do coração','Começar exercícios de mobilidade em 48 h (escrever alfabeto com o pé), depois fortalecimento e propriocepção (equilíbrio em 1 pé) — ↓ recidiva em 40%','Tornozeleira por 2–4 semanas; evitar salto e terreno irregular; retorno ao esporte quando sem dor, edema e com força/equilíbrio simétricos (2–6 semanas)','Evitar calor, massagem e álcool nas primeiras 48–72 h'],al:['Incapacidade de apoiar o pé após 3–5 dias, deformidade, dor óssea persistente (fratura não vista — repetir RX/RM)','Dor intensa na panturrilha, edema progressivo, pé frio/pálido (síndrome compartimental, TVP)','Instabilidade recorrente ou dor > 6 semanas (lesão osteocondral, sindesmose — ortopedia)'],ref:'Vuurberg BJSM 2018 (diretriz holandesa); Cochrane 2002/2013 (imobilização funcional); Doherty BJSM 2017; OBLIGATO Lancet 2009; Ottawa Ankle Rules (Stiell); Cochrane 2015 (AINE tópico).'},
{n:'Crise de gota (artrite gotosa aguda)',cid:'M10.9',sp:'Reumatologia',ps:[{v:'VO / EV / INTRA-ARTICULAR',i:['Iniciar < 24 h do início: naproxeno 500 mg VO (ou ibuprofeno 800 mg / etoricoxibe 120 mg) OU colchicina 1 mg + 0,5 mg após 1 h (esquema de baixa dose = alta dose, menos diarreia — AGREE) OU prednisona 30–35 mg VO — todos equivalentes (meta-análises)','Cetoprofeno 100 mg EV se dor intensa (evitar AINE em DRC, IC, úlcera, anticoagulado → preferir corticoide)','Artrocentese se dúvida: cristais em agulha birrefringência negativa; sempre excluir artrite séptica (febre, leucocitose, monoartrite com fator de risco → Gram/cultura)','Mono/oligoartrite acessível: triancinolona 40 mg (joelho) / 10–20 mg (pequena articulação) intra-articular','Ácido úrico sérico na crise pode ser normal (não exclui); creatinina, glicemia, perfil lipídico','NÃO iniciar nem suspender alopurinol na crise (se já usa, manter)']}],casa:[{v:'USO ORAL',i:[['Naproxeno 500 mg (ou ibuprofeno 600–800 mg 8/8 h / etoricoxibe 90–120 mg 1×/dia)','14 comprimidos','Tomar 1 comprimido de 12/12 h após as refeições até 2–3 dias após o fim da dor (5–7 dias)'],['OU Colchicina 0,5 mg','20 comprimidos','Tomar 2 comprimidos (1 mg) agora e 1 comprimido após 1 h; a partir do dia seguinte, 1 comprimido de 12/12 h até resolver (≤ 7 dias); reduzir se DRC/diarreia'],['OU Prednisona 20 mg','10 comprimidos','Tomar 1½–2 comprimidos (30–40 mg) pela manhã por 5 dias (sem desmame)'],['Omeprazol 20 mg','10 cápsulas','Tomar 1 cápsula em jejum enquanto usar AINE/corticoide'],['Colchicina 0,5 mg (profilaxia ao iniciar hipouricemiante — 3–6 meses)','90 comprimidos','Tomar 1 comprimido 1×/dia (12/12 h se peso > 70 kg e função renal normal)'],['Alopurinol 100 mg (iniciar 2 semanas após a crise, ou durante com cobertura — ACR 2020 aceita; meta: AU < 6 mg/dL, < 5 se tofos)','30 comprimidos','Tomar 1 comprimido 1×/dia; aumentar 100 mg a cada 2–5 semanas até meta (dose usual 300–600 mg; ajustar na DRC)']]}],ori:['Repouso da articulação, gelo local 20 min 4×/dia, elevação; hidratação 2 L/dia','Indicações de hipouricemiante: ≥ 2 crises/ano, tofos, erosões, urolitíase, DRC ≥ 3 → tratar para a meta (treat-to-target) por toda a vida; dosar ácido úrico a cada 2–5 semanas na titulação','Reduzir: álcool (cerveja/destilados), carnes vermelhas/vísceras/frutos do mar, refrigerante e sucos com frutose; preferir laticínios desnatados, café, cerejas; perder peso','Revisar: tiazídicos e diuréticos de alça (trocar por losartana/anlodipino se possível), AAS baixa dose (manter se indicado), ciclosporina','HLA-B*5801 em asiáticos/afrodescendentes antes do alopurinol (síndrome de hipersensibilidade)'],al:['Febre alta, calafrios, articulação muito quente com toxemia (artrite séptica — punção urgente)','Rash cutâneo, febre, lesão oral após iniciar alopurinol (SUSPENDER — DRESS/SJS)','Diarreia intensa/vômitos/fraqueza muscular com colchicina (toxicidade — suspender)','Crises recorrentes, tofos, litíase, DRC'],ref:'ACR Gout Guideline 2020 (FitzGerald); EULAR 2016; BSR 2017; AGREE (Terkeltaub 2010 — colchicina baixa dose); Janssens Lancet 2008 (prednisolona = naproxeno); Rainer Ann Intern Med 2016 (prednisolona = indometacina); Cochrane 2021; SBR 2019.'},
{n:'Cervicalgia / torcicolo agudo',cid:'M54.2',sp:'Ortopedia',ps:[{v:'VO / IM',i:['Ibuprofeno 600 mg VO ou cetoprofeno 100 mg EV; dipirona 1 g','Ciclobenzaprina 5–10 mg VO se espasmo intenso (sedação)','Calor local; sem colar cervical (atrasa recuperação) exceto trauma com critérios (NEXUS/Canadian C-Spine → RX/TC)','Red flags: trauma, déficit neurológico (fraqueza/parestesia nos braços, sinal de Lhermitte, alteração de marcha/esfíncteres — mielopatia), febre, câncer, imunossupressão, rigidez de nuca com febre (meningite), dor torácica irradiada (dissecção/IAM), cefaleia occipital súbita (dissecção vertebral)']}],casa:[{v:'USO ORAL',i:[['Ibuprofeno 600 mg (ou naproxeno 500 mg 12/12 h / diclofenaco 50 mg 8/8 h)','15 comprimidos','Tomar 1 comprimido de 8/8 h após as refeições por 5 dias'],['Dipirona 500 mg','20 comprimidos','Tomar 1 comprimido de 6/6 h se dor'],['Ciclobenzaprina 5 mg (ou tizanidina 2 mg)','7 comprimidos','Tomar 1 comprimido à noite por até 7 dias (sonolência)']]},{v:'USO TÓPICO',i:[['Diclofenaco 1% gel','1 bisnaga','Aplicar com massagem suave 3×/dia por 7 dias']]}],ori:['Calor local (compressa/bolsa quente) 20 min 3×/dia; manter o pescoço em movimento — exercícios suaves de amplitude e alongamento várias vezes ao dia','Ajustar travesseiro (altura do ombro ao pescoço, posição lateral/supina), ergonomia do computador/celular (tela na altura dos olhos), pausas a cada 30–60 min','Fisioterapia/exercícios de fortalecimento se > 2 semanas; manipulação/mobilização tem benefício modesto; evitar colar cervical','Recuperação habitual em 1–2 semanas (torcicolo) a 4–6 semanas (cervicalgia mecânica)'],al:['Fraqueza/dormência progressiva em braços ou pernas, dificuldade para andar, incontinência (mielopatia) → PS','Febre com rigidez de nuca, cefaleia intensa, vômitos (meningite)','Dor após trauma importante, idoso em queda, dor com perda de peso/câncer, dor noturna intensa','Dor > 6 semanas sem melhora (RM, ortopedia/neurocirurgia)'],ref:'Bier Phys Ther 2018 (KNGF); Blanpied JOSPT 2017 (APTA); Cochrane 2015 (exercício), 2015 (AINE), 2012 (relaxantes); NEXUS/Canadian C-Spine Rule; NICE CKS.'},
{n:'Tendinopatia / bursite (ombro, cotovelo, quadril)',cid:'M75 / M77 / M70',sp:'Ortopedia',ps:[{v:'VO / EV / INFILTRAÇÃO',i:['Ibuprofeno 600 mg VO ou cetoprofeno 100 mg EV; dipirona 1 g; gelo 15–20 min','Bursite trocantérica/subacromial muito dolorosa: infiltração com triancinolona 20–40 mg + lidocaína 2% 2–4 mL (alívio rápido a curto prazo; evitar repetir < 3 meses, máx. 3/ano; não infiltrar tendão de Aquiles/patelar)','Tipoia por poucos dias apenas se dor intensa no ombro (evitar imobilização prolongada → capsulite adesiva)','RX se trauma, > 50 anos com dor noturna, suspeita de calcificação; USG/RM se sem melhora em 6 semanas ou suspeita de ruptura']}],casa:[{v:'USO ORAL',i:[['Naproxeno 500 mg (ou ibuprofeno 600 mg 8/8 h / etoricoxibe 90 mg 1×/dia)','14 comprimidos','Tomar 1 comprimido de 12/12 h após as refeições por 7 dias'],['Dipirona 500 mg','20 comprimidos','Tomar 1 comprimido de 6/6 h se dor'],['Omeprazol 20 mg (se risco GI)','7 cápsulas','Tomar 1 cápsula em jejum enquanto usar AINE']]},{v:'USO TÓPICO',i:[['Diclofenaco 1% gel ou Cetoprofeno 2,5% gel (eficácia semelhante ao oral em tendinopatias superficiais — epicondilite, Aquiles)','1 bisnaga','Aplicar 3–4×/dia por 14 dias']]}],ori:['Repouso relativo (evitar o gesto que dói — movimentos acima da cabeça, pegar peso), mas manter mobilidade; gelo 15–20 min 3×/dia nos primeiros dias','FISIOTERAPIA com exercícios excêntricos/progressivos de carga é o tratamento com melhor evidência a médio prazo (superior à infiltração após 6–12 semanas); ondas de choque na calcificada','Epicondilite: órtese de contra-força (banda), fortalecimento excêntrico de extensores; evitar infiltração com corticoide (pior desfecho em 1 ano)','Avaliar ergonomia/atividade repetitiva; retorno gradual ao esporte; evolução de semanas a meses'],al:['Perda súbita de força (ruptura do manguito/tendão), deformidade (Popeye), impossibilidade de elevar o braço','Dor intensa com febre, calor e rubor (bursite séptica/artrite séptica — punção)','Dor noturna progressiva sem relação com movimento, perda de peso (tumor/metástase)','Sem melhora após 6–12 semanas de fisioterapia adequada'],ref:'Cochrane 2016 (exercício no ombro), 2020 (manipulação), 2013 (infiltração); Coombes Lancet 2010 (corticoide nas tendinopatias — pior a longo prazo); Lin BJSM 2020; NICE CKS; SBOT.'},
/* ===== DERMATOLOGIA / INFECÇÕES DE PELE ===== */
{n:'Celulite / Erisipela',cid:'L03.9 / A46',sp:'Dermatologia',ps:[{v:'IM / EV / VO',i:['Delimitar a borda com caneta e anotar hora; elevar o membro; dipirona 1 g','Erisipela típica (borda nítida, elevada — estreptococo): penicilina G benzatina 1.200.000 UI IM (repetir em 7 dias se grave) ou penicilina cristalina/procaína','Celulite sem purulência (sem abscesso): 1ª dose cefalexina 1 g VO ou cefazolina 1–2 g EV','Celulite purulenta/abscesso/MRSA suspeito (uso de drogas EV, recorrente, atleta, pós-drenagem): SMX-TMP ou clindamicina; drenar coleções (USG)','Internar (SIRS, imunossuprimido, face/periorbitária, mão, rapidamente progressiva, falha oral, bolhas/necrose): ceftriaxona 1 g EV 12/12 h ou oxacilina 2 g EV 4/4 h (± vancomicina)','Prednisona 40 mg VO 7 dias como adjuvante (não diabético) acelera resolução (Bergkvist 1997; IDSA sugere)','Tratar porta de entrada: tinea pedis, fissuras, úlceras; glicemia; Doppler se dúvida com TVP']}],casa:[{v:'USO ORAL',i:[['Cefalexina 500 mg — 1ª escolha (celulite não purulenta)','28 cápsulas','Tomar 1 cápsula de 6/6 h por 5–7 dias (2 cápsulas = 1 g de 6/6 h se > 80–100 kg ou celulite extensa); estender se não resolvida'],['OU Amoxicilina 500 mg (erisipela — estreptococo)','30 cápsulas','Tomar 2 cápsulas (1 g) de 8/8 h por 7 dias (se não fez benzatina)'],['OU Sulfametoxazol + trimetoprima 800/160 mg (purulenta/MRSA)','20 comprimidos','Tomar 1–2 comprimidos de 12/12 h por 7 dias'],['OU Clindamicina 300 mg (alergia a penicilina)','28 cápsulas','Tomar 1 cápsula de 6/6 h por 7 dias'],['Dipirona 500 mg ou Ibuprofeno 600 mg','20 comprimidos','Tomar 1 comprimido de 8/8 h se dor ou febre'],['Prednisona 20 mg (adjuvante, se não diabético)','14 comprimidos','Tomar 2 comprimidos pela manhã por 7 dias']]},{v:'USO TÓPICO (porta de entrada)',i:[['Terbinafina 1% creme (se frieira/tinea pedis)','1 bisnaga','Aplicar entre os dedos 2×/dia por 2–4 semanas']]}],ori:['Elevar o membro acima do coração o máximo possível (↓ edema, dor e acelera cura); repouso relativo; hidratação','Retorno em 48–72 h: eritema pode avançar um pouco nas primeiras 24–48 h (inflamação) mesmo com antibiótico correto — febre deve ceder','Erisipela recorrente (≥ 3–4 episódios/ano): penicilina benzatina 1.200.000 UI IM a cada 3–4 semanas por 6–12 meses (PATCH I, NEJM 2013); tratar linfedema/insuficiência venosa, micose interdigital, hidratação da pele','Atualizar tétano se ferimento'],al:['Febre persistente > 72 h de antibiótico, progressão além da marcação, bolhas hemorrágicas, dor desproporcional, crepitação, anestesia da pele, toxemia (fasciíte necrosante — cirurgia URGENTE)','Flutuação (abscesso) → drenar','Celulite facial/periorbitária com dor ocular, proptose, alteração visual (celulite orbitária)'],ref:'IDSA SSTI 2014 (Stevens); PATCH I NEJM 2013 (Thomas); Cochrane 2010 (intervenções) e 2017 (profilaxia); Moran NEJM 2017 (cefalexina ± SMX-TMP); SBD.'},
{n:'Abscesso cutâneo / furúnculo',cid:'L02.9',sp:'Dermatologia',ps:[{v:'PROCEDIMENTO / VO',i:['INCISÃO E DRENAGEM é o tratamento (antibiótico isolado é insuficiente): antissepsia, anestesia local (lidocaína 2% sem vaso em campo/bloqueio), incisão ampla ao longo das linhas de força, rompimento de loculações, lavagem com SF, considerar dreno/curativo úmido por 24–48 h (ou loop drain — menos dor, igual eficácia)','USG point-of-care se dúvida entre celulite e abscesso (coleção)','Antibiótico APÓS a drenagem (↑ cura em ~7% e ↓ recorrência — NEJM 2016/2017): SMX-TMP ou clindamicina, sobretudo se: ≥ 2 cm, celulite extensa ao redor, múltiplas lesões, febre, imunossupressão/diabetes, face/mão/genital, prótese, falha de drenagem','Furúnculo pequeno sem flutuação: compressas quentes; não espremer (sobretudo no "triângulo da face")','Cultura do pus se recorrente, grave ou falha; dipirona 1 g; tétano em dia']}],casa:[{v:'USO ORAL',i:[['Sulfametoxazol + trimetoprima 800/160 mg — 1ª escolha após drenagem (cobre MRSA comunitário)','14 comprimidos','Tomar 1 comprimido de 12/12 h por 7 dias (2 comprimidos de 12/12 h se > 100 kg)'],['OU Clindamicina 300 mg','28 cápsulas','Tomar 1 cápsula de 6/6 h por 7 dias'],['OU Cefalexina 500 mg (se celulite estreptocócica associada e baixo risco de MRSA)','28 cápsulas','Tomar 1 cápsula de 6/6 h por 7 dias'],['Dipirona 500 mg ou Ibuprofeno 600 mg','10 comprimidos','Tomar 1 comprimido de 8/8 h se dor']]},{v:'USO TÓPICO — curativo da cavidade drenada',i:[['Soro fisiológico 0,9% + gaze estéril + micropore','1 frasco + 1 pacote','Lavar a ferida com SF e trocar o curativo 1–2×/dia; retirar o dreno/mecha em 24–48 h (retorno)']]},{v:'OPCIONAL — SOMENTE SE FURÚNCULOS/ABSCESSOS RECORRENTES (descolonização de S. aureus do paciente e de todos da casa; não trata o abscesso atual)',i:[['Mupirocina 2% pomada NASAL','1 bisnaga por pessoa','Aplicar pequena quantidade dentro de cada narina (cotonete) de 12/12 h por 5 dias — o nariz é o reservatório do S. aureus que causa os furúnculos de repetição'],['Clorexidina 2–4% degermante (banho)','1 frasco','Banho diário do pescoço aos pés por 5–14 dias, junto com a mupirocina nasal']]}],ori:['Compressas mornas 15 min 3–4×/dia; manter a ferida aberta cicatrizando por segunda intenção; trocar o curativo 1–2×/dia com SF e gaze; retirar dreno/mecha em 24–48 h (retorno no PS/UBS)','Lavar as mãos, não compartilhar toalhas/lâminas, lavar roupas em água quente; não espremer lesões','Recorrência: investigar diabetes, HIV, obesidade, higiene, hidradenite; descolonização de S. aureus (mupirocina nasal + clorexidina) para o paciente e contatos domiciliares','Retorno em 48–72 h para reavaliar a cavidade'],al:['Febre, calafrios, eritema que progride, estrias vermelhas (linfangite), dor intensa, abscesso que recoleta','Lesão na face central (nariz/lábio superior) com edema/dor/febre — risco de trombose do seio cavernoso','Abscesso perianal, mamário profundo, cervical com disfagia/trismo, de mão com dor à extensão dos dedos (tenossinovite) → cirurgia/especialista'],ref:'IDSA SSTI 2014; Talan NEJM 2016 (SMX-TMP após drenagem); Daum NEJM 2017 (clindamicina/SMX-TMP); Cochrane 2018 (antibiótico pós-drenagem); Gottlieb Ann Emerg Med 2018 (loop drain).'},
{n:'Urticária aguda / angioedema (sem anafilaxia)',cid:'L50.9 / T78.3',sp:'Dermatologia',ps:[{v:'IM / EV / VO',i:['Checar critérios de anafilaxia (pele + respiratório/cardiovascular/GI) → adrenalina IM imediatamente (ver "Anafilaxia")','Anti-H1 de 2ª geração VO é 1ª linha mesmo no PS: loratadina 10 mg / fexofenadina 180 mg / bilastina 20 mg (pode dar dose dobrada)','Prurido intenso/extenso: prometazina 50 mg (2 mL) IM ou difenidramina 50 mg EV (sedação; não superior ao de 2ª geração a longo prazo)','Angioedema de face/língua ou urticária extensa refratária: prednisona 40 mg VO (ou hidrocortisona 200 mg EV / metilprednisolona 40–80 mg EV) por 3–5 dias — corticoide NÃO acrescenta benefício em urticária simples (Barniol 2018)','Angioedema SEM urticária em uso de IECA (bradicinínico — não responde a anti-H1/corticoide/adrenalina): suspender IECA, observar via aérea; icatibanto/plasma fresco se grave; angioedema hereditário: C1-inibidor','Identificar e suspender gatilho: AINE/AAS, antibióticos (betalactâmicos), contraste, alimentos, picadas, infecções virais (causa mais comum de urticária aguda)','Observação 1–2 h; alta se sem sinais sistêmicos e com via aérea livre']}],casa:[{v:'USO ORAL',i:[['Loratadina 10 mg (ou desloratadina 5 mg / fexofenadina 180 mg / bilastina 20 mg / cetirizina 10 mg)','30 comprimidos','Tomar 1 comprimido 1×/dia (pode aumentar até 2 comprimidos 12/12 h — 4× a dose — se não controlar), diariamente por 7–14 dias, depois conforme necessidade'],['Hidroxizina 25 mg (opcional, para prurido noturno intenso)','10 comprimidos','Tomar 1 comprimido à noite por até 5 dias (sonolência; evitar em idosos/motoristas)'],['Prednisona 20 mg (APENAS se angioedema ou urticária grave/refratária)','10 comprimidos','Tomar 2 comprimidos (40 mg) pela manhã por 3–5 dias']]}],ori:['Urticária aguda (< 6 semanas) é autolimitada em dias a semanas; na maioria não se identifica a causa (viral) — exames não são necessários','Evitar AINE/AAS (pioram urticária mesmo sem ser a causa), álcool, calor, roupas apertadas, estresse; banho morno/frio alivia; anotar possíveis desencadeantes','Anti-H1 de 1ª geração (dexclorfeniramina, prometazina) não são recomendados como padrão (sedação, menor eficácia)','Se persistir > 6 semanas = urticária crônica → alergista (anti-H1 até 4× dose, omalizumabe); se reação a medicamento, registrar alergia'],al:['Edema de lábios/língua/garganta com dificuldade para engolir ou respirar, rouquidão, chiado, tontura/hipotensão, vômitos/cólicas intensas → ANAFILAXIA: SAMU 192 e adrenalina','Lesões que duram > 24 h no mesmo lugar, deixam manchas roxas, com febre/artralgia (vasculite urticariforme — biópsia)','Angioedema recorrente sem urticária (hereditário/IECA)'],ref:'EAACI/GA²LEN/EuroGuiDerm/APAAACI Urticaria Guideline 2022 (Zuberbier); Barniol Ann Emerg Med 2018 (corticoide sem benefício); Cochrane 2014; ASBAI 2019; SBD.'},
{n:'Herpes-zóster',cid:'B02.9',sp:'Dermatologia',ps:[{v:'VO / EV',i:['Iniciar antiviral o quanto antes — melhor benefício se ≤ 72 h do início do rash (iniciar mesmo depois se lesões novas, acometimento oftálmico, imunossuprimido, > 50 anos ou dor intensa)','Analgesia: dipirona 1 g + AINE (cetoprofeno 100 mg EV) na fase aguda; se moderada-grave: tramadol 50–100 mg; iniciar gabapentina/pregabalina ou amitriptilina (↓ dor aguda e possivelmente NPH)','Internar/EV (aciclovir 10 mg/kg EV 8/8 h): imunossuprimido grave, disseminado (> 2 dermátomos/> 20 lesões fora), oftálmico com acometimento ocular, Ramsay-Hunt grave, encefalite/mielite, gestante grave','Zóster oftálmico (V1 — ponta do nariz = sinal de Hutchinson): oftalmologia URGENTE; corticoide tópico ocular só com oftalmo','Corticoide sistêmico: não reduz NPH; opcional para dor aguda intensa em imunocompetente (prednisona 40 mg 7 d, desmame) — benefício duvidoso','Vacinar após recuperação (recombinante, 2 doses) — reduz recorrência'],}],casa:[{v:'USO ORAL',i:[['Valaciclovir 1 g (ou 500 mg × 2) — preferível (posologia e níveis)','21 comprimidos','Tomar 1 g de 8/8 h por 7 dias'],['OU Aciclovir 400 mg (disponível no SUS)','70 comprimidos','Tomar 2 comprimidos (800 mg) 5×/dia (acordado, a cada ~4 h) por 7 dias, com bastante água'],['OU Fanciclovir 500 mg','21 comprimidos','Tomar 1 comprimido de 8/8 h por 7 dias'],['Dipirona 1 g','20 comprimidos','Tomar 1 comprimido de 6/6 h se dor'],['Gabapentina 300 mg (dor neuropática moderada-grave) — ou pregabalina 75 mg 12/12 h','30 cápsulas','Tomar 1 cápsula à noite por 3 dias, depois 1 de 12/12 h por 3 dias, depois 1 de 8/8 h (titular até 900–1.800 mg/dia; reduzir na DRC/idoso)'],['OU Amitriptilina 25 mg (se < 65 anos, sem cardiopatia/glaucoma/retenção urinária)','30 comprimidos','Tomar ½–1 comprimido à noite'],['Tramadol 50 mg (resgate)','10 cápsulas','Tomar 1 cápsula de 8/8 h se dor intensa, por até 5 dias']]},{v:'USO TÓPICO',i:[['Compressas frias com SF 0,9% ou água boricada 3%; solução de permanganato de potássio 1:40.000 (se exsudato)','—','Aplicar 10–15 min 3×/dia; manter lesões limpas e secas; não usar pomadas oclusivas/antivirais tópicos (sem eficácia)'],['Lidocaína 5% adesivo ou gel (após cicatrização, se neuralgia)','—','Aplicar na área dolorosa até 12 h/dia']]}],ori:['Contagioso para quem nunca teve varicela/não vacinado (contato com as lesões até formarem crosta ~7–10 dias): cobrir as lesões, evitar gestantes, RN e imunossuprimidos; não é necessário afastamento se lesões cobertas','Roupas leves de algodão; não coçar/estourar vesículas; banho com sabonete neutro; unhas curtas','Dor pode persistir após a cicatrização (neuralgia pós-herpética — risco ↑ > 50–60 anos, dor intensa inicial, rash extenso) — retorno se dor > 4 semanas: ajustar gabapentina/amitriptilina, lidocaína tópica, capsaicina, bloqueio','Investigar imunossupressão (HIV) se < 50 anos sem causa, recorrente ou disseminado; vacina recombinante após a cura'],al:['Lesões próximas ao olho/ponta do nariz, olho vermelho, dor ocular, visão embaçada (zóster oftálmico — oftalmologia urgente)','Lesões no ouvido/paralisia facial/vertigem (Ramsay-Hunt)','Lesões que se espalham por todo o corpo, febre alta, confusão, cefaleia intensa, fraqueza em membro (disseminação/encefalite/mielite)','Secreção purulenta, celulite ao redor (infecção bacteriana secundária)'],ref:'IDSA/Dworkin CID 2007; Cochrane 2014 (antivirais) e 2013 (corticoide); Werner EADV 2017; AAN NPH 2004; SBD; Shingrix (ZOE-50/70 NEJM 2015/2016).'},
{n:'Escabiose (sarna)',cid:'B86',sp:'Dermatologia',ps:[{v:'VO / TÓPICO',i:['Diagnóstico clínico: prurido noturno intenso, pápulas/túneis em espaços interdigitais, punhos, axilas, cintura, nádegas, genitais, aréolas; contatos com prurido; dermatoscopia (sinal do "asa-delta")','Ivermectina 200 mcg/kg VO (1 comprimido de 6 mg a cada 30 kg) dose única no PS — repetir em 7–14 dias (não age nos ovos)','Prurido: anti-H1 (loratadina 10 mg; hidroxizina 25 mg à noite)','Infecção secundária (impetiginização — comum): cefalexina 500 mg 6/6 h 7 dias; tratar antes/junto da escabicida','Sarna crostosa (norueguesa — imunossuprimidos/idosos/institucionalizados): ivermectina dias 1, 2, 8, 9, 15 (+22, 29 se grave) + permetrina diária por 7 dias → internação/isolamento de contato']}],casa:[{v:'USO TÓPICO',i:[['Permetrina 5% loção ou creme — 1ª escolha (≥ 2 meses; gestante/lactante OK)','1–2 frascos de 60 mL (por pessoa)','Aplicar à noite, após o banho, em TODO o corpo do pescoço aos pés (incluindo entre dedos, sob unhas, genitais, nádegas; no idoso/lactente incluir couro cabeludo e face), deixar agir 8–14 h e enxaguar pela manhã. REPETIR após 7 dias. Tratar TODOS os contatos domiciliares no mesmo dia, mesmo sem coceira'],['Hidratante (ureia 5–10% ou óleo de amêndoas) e Hidrocortisona 1% creme (prurido pós-escabiótico)','1 bisnaga','Aplicar nas áreas de prurido 2×/dia por 7–14 dias, após o tratamento escabicida']]},{v:'USO ORAL',i:[['Ivermectina 6 mg (alternativa/associação em casos extensos, falha, surtos, difícil adesão ao tópico; contraindicada em < 15 kg, gestantes e lactantes)','2 comprimidos a cada 30 kg (ex.: 60 kg = 2 cp por dose)','Tomar 200 mcg/kg (1 comprimido de 6 mg para cada 30 kg) em dose única com água, em jejum ou 2 h após refeição; REPETIR a mesma dose em 7–14 dias'],['Loratadina 10 mg (dia) e/ou Hidroxizina 25 mg (noite)','10 + 10 comprimidos','Loratadina 1 comprimido pela manhã; hidroxizina 1 comprimido à noite se prurido intenso, por 7–10 dias'],['Cefalexina 500 mg (apenas se lesões com pus/crostas melicéricas)','28 cápsulas','Tomar 1 cápsula de 6/6 h por 7 dias']]}],ori:['Tratar simultaneamente todos os moradores e contatos íntimos (mesmo sem sintomas) — a principal causa de "falha" é a reinfestação','No dia do tratamento: lavar roupas de cama, toalhas e roupas usadas nos últimos 3 dias em água quente (≥ 60 °C) e secar ao sol/ferro; o que não puder lavar, guardar em saco plástico fechado por 72 h; aspirar sofás/colchões','O prurido pode persistir por 2–4 semanas após o tratamento eficaz (reação aos ácaros mortos) — não significa falha; usar hidratante/anti-H1/corticoide tópico; só repetir escabicida se lesões novas após 2–4 semanas','Afastamento de escola/trabalho por 24 h após a 1ª aplicação; unhas curtas e limpas','Evitar banhos muito quentes e escabicidas em excesso (dermatite irritativa)'],al:['Lesões com pus, crostas amareladas, febre, gânglios (infecção secundária — risco de glomerulonefrite pós-estreptocócica)','Crostas espessas/descamação difusa (sarna crostosa) — altamente contagiosa; imunossupressão','Lesões novas 2–4 semanas após tratamento correto (reinfestação/resistência)'],ref:'IACS/European Guideline for Management of Scabies 2017 (Salavastru); Cochrane 2018 (permetrina = ivermectina em 2 doses); CDC 2019; SBD; Rosumeck 2018 (meta-análise).'},
{n:'Impetigo (adulto) / foliculite',cid:'L01.0 / L73.9',sp:'Dermatologia',ps:[{v:'TÓPICO / VO',i:['Remover crostas com compressas mornas de SF 0,9% ou água + sabonete antisséptico; limpeza suave','Impetigo localizado (poucas lesões): tópico apenas — mupirocina 2% ou ácido fusídico 2% (superiores ou iguais ao antibiótico oral — Cochrane)','Extenso (> 5 lesões/múltiplas áreas), bolhoso disseminado, febre, linfadenopatia, imunossupressão, surtos domiciliares: antibiótico oral (cefalexina; SMX-TMP se MRSA)','Foliculite superficial: clorexidina + mupirocina tópica; furúnculo → ver "Abscesso"; foliculite de banheira/pseudomonas: autolimitada','Cultura se recorrente, falha ou suspeita de MRSA']}],casa:[{v:'USO TÓPICO',i:[['Mupirocina 2% pomada (ou ácido fusídico 2% creme / retapamulina 1%)','1 bisnaga','Aplicar nas lesões, após retirar crostas, de 8/8 h por 5–7 dias'],['Clorexidina 2% degermante (ou sabonete antisséptico)','1 frasco','Lavar as lesões e as mãos 2×/dia; banho diário']]},{v:'USO ORAL (se extenso)',i:[['Cefalexina 500 mg','28 cápsulas','Tomar 1 cápsula de 6/6 h por 7 dias'],['OU Sulfametoxazol + trimetoprima 800/160 mg (suspeita de MRSA/alergia)','14 comprimidos','Tomar 1 comprimido de 12/12 h por 7 dias'],['OU Azitromicina 500 mg (alergia; menor eficácia contra S. aureus)','3 comprimidos','Tomar 1 comprimido 1×/dia por 3 dias'],['Loratadina 10 mg (se prurido)','7 comprimidos','Tomar 1 comprimido 1×/dia']]}],ori:['Altamente contagioso: lavar as mãos com frequência, unhas curtas, não compartilhar toalhas/roupas/lâminas, trocar fronhas diariamente; cobrir lesões; afastamento de trabalho (manipulação de alimentos, creche, saúde) até 24–48 h de antibiótico','Não coçar; tratar a causa de base (dermatite atópica, escabiose, picadas, barbear — foliculite)','Lesões cicatrizam sem marca em 7–10 dias; retorno se sem melhora em 3–5 dias (MRSA, outro diagnóstico — herpes, tinea)','Recorrente: descolonização nasal com mupirocina 5 dias + banhos de clorexidina; glicemia; investigar portador na família'],al:['Febre, mal-estar, gânglios dolorosos, celulite ao redor, bolhas grandes/descolamento da pele (síndrome da pele escaldada), dor intensa','Urina escura/espumosa, edema facial, PA alta 1–3 semanas após (glomerulonefrite pós-estreptocócica)','Lesões crônicas, ulceradas (ectima) ou sem resposta'],ref:'IDSA SSTI 2014; Cochrane 2012 (Koning — tópico ≥ oral); Hartman-Adams AFP 2014; SBD; NICE NG153 2020.'},
{n:'Dermatite de contato / eczema agudo',cid:'L25.9 / L23',sp:'Dermatologia',ps:[{v:'VO / IM / TÓPICO',i:['Afastar o agente (níquel, borracha, cosmético, planta, cimento, luvas, medicamentos tópicos — neomicina, anestésicos); lavar a área com água corrente','Lesões exsudativas/bolhosas: compressas frias com SF 0,9% ou água boricada 3% 15 min 3–4×/dia; drenar bolhas grandes mantendo o teto','Prurido intenso: anti-H1 oral (loratadina 10 mg; hidroxizina 25 mg à noite); prometazina 50 mg IM se insônia por prurido (anti-H1 não age na dermatite de contato alérgica em si, só no prurido)','Extensa (> 20% da superfície), face/genitais/mãos graves, disseminada: prednisona 0,5–1 mg/kg (40–60 mg) VO por 7 dias com desmame em 2–3 semanas (desmame curto < 2 sem → rebote); evitar corticoide de depósito IM de rotina','Infecção secundária (pústulas, crostas melicéricas, dor): cefalexina 500 mg 6/6 h 7 d','Investigar: ocupacional (CAT), fotossensibilidade, dermatite atópica; teste de contato (patch test) com dermatologista após a fase aguda']}],casa:[{v:'USO TÓPICO',i:[['Mometasona 0,1% creme (ou betametasona valerato 0,1% / desonida 0,05% para face, dobras e genitais)','1 bisnaga','Aplicar fina camada nas lesões 1×/dia (mometasona) ou 2×/dia (outros) por 7–14 dias; na face/dobras no máximo 7 dias'],['Compressas de SF 0,9% ou água boricada 3% (fase úmida)','—','Aplicar gaze/pano embebido 15 min 3–4×/dia enquanto houver secreção/bolhas'],['Hidratante sem perfume (ceramidas/ureia 5%) — após a fase aguda','1 frasco','Aplicar 2–3×/dia, inclusive após o banho']]},{v:'USO ORAL',i:[['Loratadina 10 mg ou Cetirizina 10 mg (dia) / Hidroxizina 25 mg (noite)','10 + 10 comprimidos','Loratadina 1 cp pela manhã; hidroxizina 1 cp à noite se prurido intenso, por 7–10 dias'],['Prednisona 20 mg (somente se extensa/grave)','30 comprimidos','Tomar 2 comprimidos (40 mg) pela manhã por 7 dias, depois 1½ cp por 4 dias, 1 cp por 4 dias e ½ cp por 4 dias'],['Cefalexina 500 mg (se infecção secundária)','28 cápsulas','Tomar 1 cápsula de 6/6 h por 7 dias']]}],ori:['Identificar e evitar o agente é o tratamento definitivo: ler rótulos (fragrância, metilisotiazolinona, níquel), luvas de vinil/nitrilo com forro de algodão, substituir cosméticos por hipoalergênicos sem perfume','Banho morno e curto, sabonete neutro/syndet, secar sem esfregar; não usar álcool, buchas, produtos "caseiros", pomadas com neomicina/anestésico','Corticoide tópico: fina camada ("unidade da ponta do dedo" por área de 2 palmas); não ocluir; não usar por > 2–4 semanas contínuas; na face/dobras só baixa potência','Evitar sol na área (hiperpigmentação); unhas curtas; roupas de algodão','Retorno em 2 semanas; dermatologista para patch test se recorrente/ocupacional/mãos crônica'],al:['Febre, pus, dor crescente, crostas amareladas (infecção)','Edema de face/pálpebras importante, dificuldade para abrir os olhos, lesões disseminadas rapidamente','Lesões em mucosas, bolhas extensas com descolamento, mal-estar (farmacodermia grave — SJS/NET)','Sem melhora após 2 semanas de tratamento e afastamento do agente'],ref:'Johansen Contact Dermatitis 2015 (ESCD guideline); AAD 2023 (Contact Dermatitis Guidelines); Cochrane 2019 (dermatite de contato ocupacional); SBD; Brasch 2014 (German guideline).'},
{n:'Dermatofitose (tinea corporis / cruris / pedis)',cid:'B35.4 / B35.6 / B35.3',sp:'Dermatologia',ps:[{v:'TÓPICO / VO',i:['Diagnóstico clínico: placa anular com borda ativa descamativa e clareamento central; confirmar com KOH (micológico direto) se dúvida ou antes de oral — não tratar "ide" com corticoide isolado (tinea incógnita)','Tratamento tópico com alilamina (terbinafina) por 2–4 semanas é suficiente na maioria (cura > 80%; superior a azólicos em velocidade — Cochrane)','Oral: extensa (> 2 áreas/múltiplas placas), tinea capitis (sempre oral — griseofulvina/terbinafina), unhas, imunossuprimido, pelos acometidos (foliculite dermatofítica/granuloma de Majocchi), falha do tópico','Não associar corticoide tópico (combinações "antifúngico + corticoide" mascaram, cronificam e favorecem recidiva/resistência — evitar); apenas se intertrigo muito inflamado por ≤ 3–5 dias','Dermatofitose recalcitrante/resistente (T. indotineae — emergente): terbinafina resistente → itraconazol 200 mg/dia 4–8 semanas']}],casa:[{v:'USO TÓPICO',i:[['Terbinafina 1% creme (ou butenafina 1% / ciclopirox olamina 1%)','1–2 bisnagas','Aplicar nas lesões e 2 cm além da borda 1–2×/dia por 2 semanas (tinea corporis/cruris) ou 4 semanas (pés — incluir entre os dedos e planta); manter por 1 semana após sumir a lesão'],['OU Cetoconazol 2% creme / Miconazol 2% / Clotrimazol 1%','1–2 bisnagas','Aplicar 2×/dia por 4 semanas (e 1–2 semanas após desaparecer)'],['Pó/spray antifúngico (miconazol 2% ou tolnaftato 1%) para calçados e dobras — prevenção','1 frasco','Aplicar nos pés/dobras e nos sapatos diariamente após secar bem']]},{v:'USO ORAL (se extensa/falha/pelos)',i:[['Terbinafina 250 mg','14–28 comprimidos','Tomar 1 comprimido 1×/dia por 2 semanas (corpo/virilha) ou 2–4 semanas (pés) — verificar função hepática se > 6 semanas; interação com alguns antidepressivos'],['OU Itraconazol 100 mg','14–28 cápsulas','Tomar 2 cápsulas (200 mg) 1×/dia com alimento por 1–2 semanas (corpo) ou 2–4 semanas (pés); não usar com estatinas/IC'],['OU Fluconazol 150 mg','4–6 comprimidos','Tomar 1 comprimido 1×/semana por 4–6 semanas']]}],ori:['Secar bem as dobras e entre os dedos após o banho (toalha separada/secador frio); usar roupas e meias de algodão, trocar diariamente; calçados arejados e alternados; chinelo em vestiário/piscina','Não compartilhar toalhas, roupas, lâminas; lavar roupas em água quente; tratar animais domésticos (gato/cão com áreas de alopecia — M. canis)','Tinea pedis é a porta de entrada mais comum para erisipela recorrente — tratar e prevenir','Continuar o creme 1–2 semanas após a melhora visual (recidiva); retorno em 4 semanas se persistir (KOH/cultura, trocar classe ou oral)','Unhas (onicomicose): confirmar com micológico antes de oral (terbinafina 250 mg/dia 6 sem mãos/12 sem pés)'],al:['Lesões que pioram/alastram apesar do tratamento, principalmente após uso de pomadas com corticoide (tinea incógnita)','Placa inflamada, dolorosa, com pústulas e perda de cabelo (kerion — oral + possivelmente prednisona)','Imunossuprimido/diabético com lesões extensas, celulite associada','Lesões nas unhas/couro cabeludo (necessitam oral)'],ref:'Cochrane 2014 (tópicos — El-Gohary); BAD Guidelines 2014 (tinea capitis) e 2015 (onicomicose); Sahoo IDOJ 2016; Ely AFP 2014; SBD; Khurana 2022 (resistência à terbinafina).'},
/* ===== INFECTOLOGIA / MEDICINA TROPICAL ===== */
{n:'Dengue (grupos A e B — ambulatorial)',cid:'A90',sp:'Infectologia',ps:[{v:'VO / EV',i:['Classificar: Grupo A (sem sinais de alarme, sem risco, prova do laço negativa) → hidratação oral em casa; Grupo B (prova do laço +, sangramento espontâneo de pele, risco: < 2 a, > 65 a, gestante, comorbidades) → hemograma no PS, hidratação oral supervisionada até resultado; Grupo C (sinais de alarme) → INTERNAR, SF 0,9% 10 mL/kg/h EV por 1–2 h, reavaliar; Grupo D (choque) → 20 mL/kg em 20 min (repetir até 3×), UTI','Prova do laço: PAM por 5 min (3 min criança) — + se ≥ 20 petéquias/2,5 cm² (≥ 10 em criança)','Dipirona 1 g VO/EV ou paracetamol 750 mg — NUNCA AAS, AINE (ibuprofeno, diclofenaco, cetoprofeno), nem corticoide (↑ sangramento; sem benefício)','Hidratação no PS se vômitos/intolerância: SF 0,9% 1000 mL EV em 2 h (adulto) ou 20 mL/kg em 2 h, depois reavaliar; ondansetrona 8 mg EV','Exames Grupo B: hemograma (hematócrito, plaquetas); NS1 (até 5º dia)/IgM (após 6º dia) para confirmação; TGO/TGP, albumina; USG se dúvida de derrame/ascite','Notificação compulsória; orientar retorno DIÁRIO no período crítico (3º–7º dia, geralmente na defervescência)']}],casa:[{v:'USO ORAL',i:[['Hidratação oral: 60 mL/kg/dia (ex.: 70 kg = 4,2 L/dia), sendo 1/3 com soro de reidratação oral e 2/3 com água, sucos, chás, água de coco, sopas','—','Começar no PS: 1/3 do volume nas primeiras 4–6 h (ex.: 1,5 L em 4 h); manter o resto ao longo do dia por 5–7 dias, até 48 h após a febre'],['Sais de reidratação oral','10 envelopes','Diluir 1 envelope em 1 L de água filtrada; tomar ~1,5 L/dia desse soro'],['Dipirona 500 mg (ou 1 g)','20 comprimidos','Tomar 1 comprimido de 6/6 h se dor ou febre (máx. 4 g/dia)'],['Paracetamol 750 mg (alternar, se necessário; máx. 3 g/dia — hepatotoxicidade na dengue)','10 comprimidos','Tomar 1 comprimido de 6/6 h se febre ou dor, intercalando com a dipirona a cada 3 h'],['Ondansetrona 4 mg (se náuseas)','6 comprimidos','Tomar 1 comprimido de 8/8 h se vômitos'],['Loratadina 10 mg (prurido na fase de recuperação)','5 comprimidos','Tomar 1 comprimido 1×/dia se coceira']]}],ori:['PROIBIDO: AAS, ibuprofeno, diclofenaco, nimesulida, cetoprofeno, naproxeno, corticoide e injeções intramusculares (risco de sangramento/hematoma)','Repouso; retornar ao serviço DIARIAMENTE (Grupo B) ou conforme cartão de acompanhamento até 48 h após o fim da febre; levar o cartão da dengue com hematócrito/plaquetas','A fase crítica começa quando a febre cede (3º–7º dia) — é quando aparecem os sinais de alarme; não suspender a hidratação porque "melhorou"','Eliminar criadouros do Aedes em casa; usar repelente (DEET/icaridina) e mosquiteiro nos primeiros 7 dias para não transmitir','Gestante, idoso, cardiopata/renal/diabético/hipertenso, asmático, DPOC, anemia falciforme, imunossuprimido = Grupo B mesmo sem alarme'],al:['SINAIS DE ALARME (retornar IMEDIATAMENTE): dor abdominal intensa e contínua, vômitos persistentes, sangramento de mucosas (gengiva, nariz, urina, fezes, menstruação volumosa), letargia/irritabilidade, tontura ao levantar/hipotensão postural, hepatomegalia > 2 cm, acúmulo de líquidos (ascite, derrame), queda brusca de plaquetas/aumento do hematócrito, diminuição da diurese','GRAVIDADE: extremidades frias, pulso fino, PA convergente (PAS–PAD ≤ 20), sangramento grave, desconforto respiratório, confusão, convulsão'],ref:'MS — Dengue: diagnóstico e manejo clínico adulto e criança 6ª ed. 2024; OMS/OPAS 2022 (Dengue guidelines for patient care); Cochrane 2014 (corticoide — sem benefício); SBI; Nota Técnica MS 2024 (Qdenga).'},
{n:'Chikungunya (fase aguda e subaguda)',cid:'A92.0',sp:'Infectologia',ps:[{v:'VO / EV',i:['Fase AGUDA (≤ 14 dias): poliartralgia intensa simétrica (mãos, punhos, tornozelos) + febre alta + exantema; tratar como dengue até excluí-la (até o 7º dia NÃO usar AINE/AAS — coinfecção/dengue pode estar presente)','Dipirona 1 g VO/EV (até 6/6 h) ± paracetamol 750 mg intercalado; dor intensa: tramadol 50–100 mg VO/EV; codeína 30 mg','Compressas frias nas articulações 20 min 4×/dia (calor piora na fase aguda); hidratação igual à dengue (60 mL/kg/dia) se febre','Corticoide: NÃO na fase aguda; na SUBAGUDA (> 14 dias até 3 meses) com artrite persistente/tenossinovite: prednisona 0,5 mg/kg/dia (20–40 mg) por 7–21 dias com desmame lento, ou AINE (naproxeno) se dengue excluída','Exames: hemograma, creatinina, TGO/TGP (ajuste de analgésicos), sorologia IgM após 5º–7º dia / RT-PCR ≤ 7 dias; PCR/VHS','Formas atípicas/graves (internar): encefalite, miocardite, hepatite, neonato (transmissão vertical), idoso frágil com comorbidades descompensadas, dor refratária, desidratação grave','Notificação compulsória']}],casa:[{v:'USO ORAL — FASE AGUDA (primeiros 7–14 dias)',i:[['Dipirona 1 g','20 comprimidos','Tomar 1 comprimido de 6/6 h se dor ou febre'],['Paracetamol 750 mg','10 comprimidos','Tomar 1 comprimido de 6/6 h intercalando com a dipirona (a cada 3 h um deles); máx. 3 g/dia'],['Tramadol 50 mg (dor intensa não controlada; evitar em idosos/epilepsia; pode associar)','20 cápsulas','Tomar 1–2 cápsulas de 8/8 h se dor intensa (máx. 400 mg/dia); causa náusea/constipação'],['Ondansetrona 4 mg','6 comprimidos','Tomar 1 comprimido de 8/8 h se náuseas'],['Sais de reidratação oral + líquidos (60 mL/kg/dia)','6 envelopes','1 envelope em 1 L de água; tomar ao longo do dia']]},{v:'USO ORAL — FASE SUBAGUDA/CRÔNICA (> 14 dias, dengue excluída)',i:[['Naproxeno 500 mg (ou ibuprofeno 600 mg 8/8 h)','14 comprimidos','Tomar 1 comprimido de 12/12 h após refeições por 7 dias (se função renal normal, sem úlcera/anticoagulante)'],['Prednisona 20 mg (artrite/tenossinovite/edema inflamatório persistente após 14 dias sem resposta ao AINE)','30 comprimidos','Tomar 1–2 comprimidos pela manhã por 7–14 dias (0,5 mg/kg), depois reduzir 5 mg a cada 3–5 dias (desmame lento para evitar rebote)'],['Omeprazol 20 mg','14 cápsulas','Tomar 1 cápsula em jejum enquanto usar AINE/corticoide'],['Amitriptilina 25 mg ou Duloxetina 30 mg (dor neuropática/crônica, sono)','30 comprimidos','Tomar 1 comprimido à noite']]}],ori:['Fase aguda: repouso, compressas FRIAS, NÃO usar AINE/AAS até excluir dengue (7–10 dias) e não aplicar injeções IM; líquidos como na dengue','Fase subaguda/crônica (> 3 meses em 30–40%): fisioterapia precoce (exercícios leves, hidroterapia), compressas mornas, retorno gradual às atividades; reumatologia se artrite > 3 meses (metotrexato/hidroxicloroquina)','Mosquiteiro e repelente nos primeiros 7 dias; eliminar criadouros','Retorno em 48–72 h se febre persistir ou dor não controlada; investigar outras artrites se > 3 meses (FR, anti-CCP)'],al:['Sinais de alarme de dengue (dor abdominal intensa, vômitos, sangramento, letargia, hipotensão) — pode ser dengue','Alteração de consciência, convulsão, dificuldade para respirar, dor torácica, icterícia, oligúria','Recém-nascido de mãe com chikungunya no periparto; idoso com comorbidade descompensada; dor incapacitante refratária (internar para analgesia)'],ref:'MS — Chikungunya: manejo clínico 2017 e Protocolo 2023; Marques Rev Bras Reumatol 2017 (SBR recomendações — fases); OPAS 2022; Simon Med Mal Infect 2015 (French guidelines).'},
{n:'Covid-19 leve / moderada (ambulatorial)',cid:'U07.1',sp:'Infectologia',ps:[{v:'VO / EV',i:['Classificar: leve (sem dispneia, SatO₂ ≥ 94%, RX normal) → ambulatorial; moderada (pneumonia sem hipoxemia) → observar/domiciliar com retorno; grave (SatO₂ < 94%, FR > 30, infiltrado > 50%) → internar + O₂ + dexametasona 6 mg + anticoagulação profilática','Dipirona 1 g VO/EV ou paracetamol 750 mg; SF 500 mL EV se desidratado','Antiviral se ≤ 5 dias de sintomas E fator de risco para gravidade (≥ 60 a, obesidade, DM, DCV, DRC, DPOC, imunossupressão, gestante, não vacinado): nirmatrelvir/ritonavir (Paxlovid®) — ↓ 89% hospitalização (EPIC-HR); checar interações (estatinas, anticoagulantes, antiarrítmicos, tacrolimo, rivaroxabana — contraindicado; ClCr < 30: evitar); alternativas: remdesivir 3 dias EV (dias 1–3) ou molnupiravir 800 mg 12/12 h 5 d (não em gestante)','NÃO prescrever: corticoide sem hipoxemia (↑ mortalidade — RECOVERY), azitromicina, ivermectina, hidroxicloroquina, antibiótico sem evidência de infecção bacteriana, anticoagulante ambulatorial de rotina','Teste: antígeno/RT-PCR; RX/TC apenas se dispneia/SatO₂ < 95%/moderada; hemograma, PCR, D-dímero, creatinina se moderada; oximetria domiciliar se risco','Isolamento: 5 dias (desde início dos sintomas) + máscara até o 10º dia se afebril 24 h e melhora; 7–10 dias se imunossuprimido/sintomas persistentes (MS 2023/CDC)']}],casa:[{v:'USO ORAL',i:[['Nirmatrelvir 150 mg + Ritonavir 100 mg (Paxlovid®) — se risco e ≤ 5 dias de sintomas','30 comprimidos (1 caixa)','Tomar 2 comprimidos de nirmatrelvir + 1 de ritonavir de 12/12 h por 5 dias (ClCr 30–60: 1 nirmatrelvir + 1 ritonavir). Suspender temporariamente estatina/colchicina; alerta para interações'],['Dipirona 500 mg (ou 1 g)','20 comprimidos','Tomar 1 comprimido de 6/6 h se dor ou febre'],['Paracetamol 750 mg','10 comprimidos','Tomar 1 comprimido de 6/6 h se febre persistente, intercalando (máx. 3 g/dia)'],['Loratadina 10 mg','7 comprimidos','Tomar 1 comprimido 1×/dia se coriza/espirros'],['Dexclorfeniramina 2 mg + Guaifenesina (ou mel 1 colher) — tosse (opcional, evidência fraca)','—','Tomar 1 comprimido à noite se tosse atrapalhar o sono']]},{v:'USO NASAL',i:[['Solução fisiológica 0,9%','1 frasco','Lavar as narinas 3–5×/dia']]}],ori:['Isolamento em quarto separado, máscara (PFF2/N95 ou cirúrgica) ao sair do quarto/contato com outros, ventilar ambientes, higiene das mãos; afastamento conforme MS','Hidratação 2–3 L/dia, repouso, alimentação; medir SatO₂ 2–3×/dia (oxímetro) se tiver fator de risco; posição prona acordado se desconforto leve e SatO₂ limítrofe (com retorno)','Dias 5–10 são os de maior risco de piora (hipoxemia silenciosa) — retornar/teleconsulta nesse período','Vacinação em dia (dose atualizada anual para ≥ 60 a/risco) após a recuperação; contactantes de risco: testar e tratar precocemente'],al:['Falta de ar, SatO₂ < 94% (ou queda ≥ 3% em relação ao basal), FR > 24, dor/pressão torácica, lábios roxos, confusão, sonolência, febre persistente > 5–7 dias, incapacidade de se hidratar → PS imediatamente','Sinais de TVP/TEP (dor na perna, dispneia súbita); dor torácica/palpitações (miocardite)'],ref:'MS — Diretrizes Covid-19 (Conitec 2023/2024: nirmatrelvir/ritonavir ≥ 65 a e imunossuprimidos no SUS); OMS Therapeutics and COVID-19 Living Guideline 2024; NIH 2024; IDSA 2024; EPIC-HR NEJM 2022; RECOVERY NEJM 2021; PANORAMIC Lancet 2023 (molnupiravir).'},
{n:'Sífilis (primária, secundária e latente)',cid:'A51 / A52 / A53',sp:'Infectologia',ps:[{v:'IM',i:['Diagnóstico: teste rápido treponêmico + VDRL (ou vice-versa); cancro duro/roséola/condiloma plano com teste reagente = tratar no mesmo dia (não aguardar o 2º teste em gestante, risco de perda de seguimento ou clínica típica)','Sífilis RECENTE (primária, secundária, latente recente < 1 ano): penicilina G benzatina 2.400.000 UI IM (1,2 milhão em cada glúteo) DOSE ÚNICA','Sífilis TARDIA (latente tardia > 1 ano, latente de duração ignorada, terciária não neurológica): benzatina 2.400.000 UI IM 1×/semana por 3 semanas (7.200.000 UI total) — intervalo ideal de 7 dias; se ultrapassar 14 dias (9 dias em gestantes — CDC), reiniciar o esquema','Neurossífilis/ocular/otossífilis: penicilina cristalina 18–24 milhões UI/dia EV (3–4 milhões 4/4 h) por 14 dias — internar','Gestante: SOMENTE benzatina (alergia → dessensibilizar); tratar parceiro; qualquer titulação reagente + sem tratamento documentado = tratar','Reação de Jarisch-Herxheimer (febre, mialgia, piora do rash 2–24 h após): orientar, paracetamol/dipirona; não é alergia; em gestante pode causar contrações — orientar','Testar HIV, hepatites B/C, gonococo/clamídia; notificar (SINAN); convocar parcerias dos últimos 90 dias (recente) e tratar com 2,4 milhões UI mesmo com teste negativo']}],casa:[{v:'USO INTRAMUSCULAR (aplicar na UBS)',i:[['Penicilina G benzatina 1.200.000 UI (frasco-ampola) — recente','2 frascos (dose única)','Aplicar 1.200.000 UI IM profundo em cada glúteo, dose única (total 2.400.000 UI), na UBS'],['Penicilina G benzatina 1.200.000 UI — tardia/duração ignorada','6 frascos (3 semanas)','Aplicar 2.400.000 UI IM (1 frasco em cada glúteo) 1× por semana por 3 semanas consecutivas (dias 0, 7 e 14) na UBS; não atrasar mais de 7 dias']]},{v:'USO ORAL — ALTERNATIVA apenas para NÃO gestante com alergia comprovada (menor eficácia; seguimento rigoroso)',i:[['Doxiciclina 100 mg','28 comprimidos (recente) / 56 (tardia)','Tomar 1 comprimido de 12/12 h por 15 dias (recente) ou 30 dias (tardia), com água, sem deitar em seguida'],['Dipirona 500 mg ou Paracetamol 750 mg (reação de Jarisch-Herxheimer)','10 comprimidos','Tomar 1 comprimido de 6/6 h se febre/dor nas primeiras 24 h após a penicilina']]}],ori:['Abstinência sexual até completar o tratamento e cicatrizar as lesões (ou 7 dias após dose única); preservativo sempre','Seguimento: VDRL/RPR trimestral no 1º ano (mensal na gestante) — resposta adequada = queda de 2 diluições (4×) em 6 meses (recente) ou 12 meses (tardia); aumento de 2 diluições = reinfecção/falha → retratar e investigar neurossífilis','Parcerias sexuais: testar e tratar presuntivamente; sífilis é marcador de risco — oferecer PrEP se indicado','Não há imunidade: pode reinfectar; cicatriz sorológica (VDRL baixo estável) não precisa retratar','Gestante: tratamento deve iniciar até 30 dias antes do parto para ser considerado adequado para o concepto; parceiro tratado; pré-natal rigoroso'],al:['Cefaleia intensa, alteração visual (uveíte/neurite — pode ser com VDRL baixo), perda auditiva, zumbido, déficit neurológico, alteração cognitiva → investigar neurossífilis/ocular (LCR, oftalmo) — penicilina cristalina EV','Reação alérgica verdadeira (urticária/anafilaxia logo após a aplicação) — diferenciar de Jarisch-Herxheimer','Gestante com contrações/diminuição de movimentos fetais após a dose (Herxheimer) → maternidade'],ref:'MS — PCDT IST 2022 (Atenção Integral às Pessoas com IST); CDC STI Treatment Guidelines 2021; OMS 2016; Nota Informativa MS 2017/2023 (benzatina na APS); Febrasgo 2023.'},
{n:'Uretrite / cervicite (gonococo e clamídia)',cid:'A54.0 / A56.0 / N34.1',sp:'Infectologia',ps:[{v:'IM / VO',i:['Tratar no mesmo dia (sindrômico) corrimento uretral/cervical mucopurulento, disúria, sangramento pós-coito: cobrir GONOCOCO + CLAMÍDIA','Ceftriaxona 500 mg IM dose única (diluir em lidocaína 1% 2 mL; 1 g se ≥ 150 kg) + Azitromicina 1 g VO dose única (MS 2022; CDC 2021 recomenda ceftriaxona + doxiciclina 7 d para clamídia — azitromicina menos eficaz em retal)','Se gonococo excluído (Gram sem diplococos / teste negativo): só clamídia — azitromicina 1 g DU ou doxiciclina 100 mg 12/12 h 7 d','Coletar antes se possível: NAAT (PCR) urina 1º jato/swab para gonococo, clamídia (e Mycoplasma genitalium se persistente); Gram; testar HIV, sífilis, hepatites B e C','Epididimite (dor/edema testicular, < 35 a): ceftriaxona 500 mg IM + doxiciclina 100 mg 12/12 h 10 d; USG Doppler se dúvida com torção','Notificar; convocar parcerias dos últimos 60 dias para tratamento igual (mesmo assintomáticas)']}],casa:[{v:'USO ORAL',i:[['Azitromicina 500 mg','2 comprimidos','Tomar 2 comprimidos (1 g) juntos, em dose única (idealmente no PS)'],['OU Doxiciclina 100 mg (preferível para clamídia — CDC 2021; contraindicada na gestação)','14 comprimidos','Tomar 1 comprimido de 12/12 h por 7 dias, com água e sem deitar em seguida'],['Para a(s) parceria(s) sexual(is): mesmo esquema — ceftriaxona 500 mg IM (na UBS) + azitromicina 1 g VO dose única','—','Tratar todos os parceiros dos últimos 60 dias, mesmo sem sintomas'],['Ibuprofeno 600 mg (se epididimite/dor)','15 comprimidos','Tomar 1 comprimido de 8/8 h por 5 dias']]},{v:'USO INTRAMUSCULAR (se não aplicado no PS)',i:[['Ceftriaxona 500 mg (1 frasco-ampola) + lidocaína 1% 2 mL','1 frasco','Aplicar IM profundo em dose única na UBS']]}],ori:['Abstinência sexual por 7 dias após o tratamento (e até que os parceiros também tenham sido tratados e assintomáticos); preservativo em todas as relações','Retestar gonococo/clamídia em 3 meses (reinfecção comum); teste de cura em 7–14 dias só na gestante, faringe ou persistência de sintomas','Uretrite persistente/recorrente após tratamento: M. genitalium (moxifloxacino 400 mg 7 d após doxiciclina) ou T. vaginalis (metronidazol 2 g) — reavaliar','Oferecer vacina hepatite B/HPV, PrEP/PEP conforme risco; teste de HIV e sífilis agora e em 30–90 dias'],al:['Dor pélvica, febre, dispareunia (DIP — ver protocolo); dor/edema testicular intenso (epididimite × torção)','Artrite + lesões cutâneas pustulosas + febre (gonococcemia disseminada — internar, ceftriaxona EV)','Olho vermelho com secreção purulenta abundante (conjuntivite gonocócica — emergência oftalmológica)','Sintomas persistentes após 7 dias do tratamento adequado'],ref:'MS — PCDT IST 2022; CDC STI Treatment Guidelines 2021 (ceftriaxona 500 mg; doxiciclina > azitromicina para clamídia — Dombrowski 2021); OMS 2016; BASHH 2019; IUSTI 2020.'},
{n:'Conjuntivite aguda (bacteriana, viral, alérgica)',cid:'H10.9',sp:'Oftalmologia',ps:[{v:'TÓPICO / VO',i:['Diferenciar: VIRAL (adenovírus — mais comum; secreção aquosa, folículos, linfonodo pré-auricular, IVAS, bilateral sequencial, muito contagiosa); BACTERIANA (secreção purulenta abundante que gruda as pálpebras, unilateral → bilateral, sem prurido); ALÉRGICA (prurido intenso, bilateral, lacrimejamento, papilas, atopia)','Sempre: acuidade visual, fluoresceína (ceratite/úlcera/corpo estranho), pupilas/reação, pressão ocular se dor; afastar glaucoma agudo, uveíte, ceratite herpética (dendritos — não dar corticoide!)','Limpeza com SF 0,9% gelado, compressas frias; lágrima artificial','Bacteriana: colírio antibiótico (tobramicina/ciprofloxacino/moxifloxacino) — encurta ~1–2 dias; autolimitada em 7 dias na maioria; obrigatório se lente de contato (cobrir Pseudomonas — quinolona), purulenta intensa, imunossuprimido','Hiperaguda com secreção purulenta copiosa (gonocócica — adulto sexualmente ativo): ceftriaxona 1 g IM + azitromicina 1 g VO + lavagem ocular frequente → oftalmo urgente (risco de perfuração)','NÃO prescrever corticoide tópico sem oftalmologista (ceratite herpética, glaucoma, catarata); não usar colírios com vasoconstritor por > 3 dias','Viral: sintomático; póvidona-iodo 0,6% / nenhum antiviral eficaz; afastamento 7–14 dias (contagioso enquanto lacrimejar)']}],casa:[{v:'USO OFTÁLMICO — BACTERIANA',i:[['Tobramicina 0,3% colírio (ou Ciprofloxacino 0,3% / Moxifloxacino 0,5% / Cloranfenicol 0,5%)','1 frasco','Pingar 1 gota no(s) olho(s) afetado(s) de 4/4 h enquanto acordado (6×/dia) por 5–7 dias; lavar as mãos antes; não encostar o bico no olho'],['Tobramicina 0,3% pomada oftálmica (opcional, à noite)','1 bisnaga','Aplicar no fundo de saco inferior ao deitar, por 5–7 dias']]},{v:'USO OFTÁLMICO — VIRAL',i:[['Lágrima artificial (carboximetilcelulose 0,5% / hialuronato 0,15%) sem conservante, gelada','1 frasco','Pingar 1–2 gotas de 2/2 h a 4/4 h enquanto acordado por 7–14 dias (manter na geladeira)'],['Compressas frias com SF 0,9% ou água filtrada gelada','—','10 min 4–6×/dia; limpar a secreção com gaze separada para cada olho']]},{v:'USO OFTÁLMICO — ALÉRGICA',i:[['Olopatadina 0,1–0,2% colírio (ou cetotifeno 0,025% / epinastina)','1 frasco','Pingar 1 gota em cada olho de 12/12 h (0,2%: 1×/dia) por 2–4 semanas ou enquanto exposição'],['Lágrima artificial gelada','1 frasco','Pingar 1 gota de 4/4 h se desconforto']]},{v:'USO ORAL (alérgica, se rinite associada)',i:[['Loratadina 10 mg / Desloratadina 5 mg / Bilastina 20 mg','10 comprimidos','Tomar 1 comprimido 1×/dia']]}],ori:['Altamente contagiosa (viral/bacteriana): lavar as mãos sempre, não coçar, toalha/fronha individuais trocadas diariamente, não compartilhar maquiagem/colírios, afastar-se de trabalho/escola enquanto houver secreção (viral: 7–14 dias)','Não usar lentes de contato até 24 h após o fim do tratamento (descartar as lentes/estojo usados); evitar maquiagem','Viral: piora nos primeiros 3–5 dias e dura 1–2 semanas (pode 3); o segundo olho costuma ser acometido; visão embaçada por infiltrados pode durar semanas','Alérgica: evitar alérgenos (poeira, pólen, pelos), não coçar (piora), óculos escuros, tratar a rinite','Nunca usar colírios "da farmácia" com corticoide ou vasoconstritor sem avaliação; não usar água boricada caseira'],al:['Dor ocular intensa (não só ardência), baixa de visão, fotofobia importante, pupila irregular/não reativa, halos coloridos, náusea/vômito (ceratite, uveíte, glaucoma agudo) → oftalmologista URGENTE','Secreção purulenta copiosa e rapidamente progressiva (gonococo); lesão dendrítica/história de herpes; usuário de lente de contato com dor/mancha branca na córnea (úlcera)','Edema palpebral com dor à movimentação ocular, proptose, febre (celulite orbitária)','Sem melhora em 5–7 dias de antibiótico ou piora em 48 h'],ref:'AAO Preferred Practice Pattern — Conjunctivitis 2018/2023; Cochrane 2023 (antibiótico na bacteriana: benefício modesto); Azari JAMA 2013 (revisão); CBO; CDC STI 2021 (gonocócica).'},
{n:'Herpes simples labial / genital',cid:'B00.1 / A60.0',sp:'Infectologia',ps:[{v:'VO',i:['LABIAL recorrente: iniciar antiviral na fase prodrômica (ardência/formigamento) — esquemas curtos de alta dose são tão eficazes quanto longos: valaciclovir 2 g 12/12 h 1 dia; tópicos (aciclovir 5% creme) têm benefício mínimo (↓ < 1 dia)','GENITAL 1º episódio (mais grave, 2–3 semanas): aciclovir 400 mg 8/8 h ou valaciclovir 1 g 12/12 h por 7–10 dias — iniciar o quanto antes, mesmo além de 72 h se lesões novas','Genital recorrente: aciclovir 800 mg 8/8 h 2 dias ou 800 mg 12/12 h 5 d; valaciclovir 500 mg 12/12 h 3 dias ou 1 g 1×/dia 5 d — iniciar no 1º dia (orientar o paciente a ter a receita em casa)','Dor: dipirona 1 g; lidocaína gel 2% tópica; banho de assento; retenção urinária por dor (1º episódio genital feminino) → sonda, internar se grave','Gestante: aciclovir é seguro; supressão com aciclovir 400 mg 8/8 h a partir de 36 semanas se história de herpes genital; lesão ativa no parto = cesárea','Testar HIV, sífilis (úlcera genital: diagnóstico diferencial — cancro duro, cancroide, donovanose); PCR/cultura da lesão se disponível; gengivoestomatite herpética primária: aciclovir 400 mg 5×/dia 7 d, hidratação','Imunossuprimido/disseminado/ocular (ceratite — oftalmo URGENTE, sem corticoide)/encefalite: aciclovir EV 5–10 mg/kg 8/8 h']}],casa:[{v:'USO ORAL — HERPES LABIAL',i:[['Valaciclovir 500 mg','8 comprimidos','Tomar 4 comprimidos (2 g) de 12/12 h por 1 dia (2 doses), iniciando ao primeiro sinal (ardência/coceira)'],['OU Aciclovir 400 mg','15 comprimidos','Tomar 1 comprimido 5×/dia (a cada 4 h, acordado) por 5 dias, iniciando ao primeiro sinal'],['Dipirona 500 mg','10 comprimidos','Tomar 1 comprimido de 6/6 h se dor']]},{v:'USO ORAL — HERPES GENITAL',i:[['Aciclovir 400 mg — 1º episódio','30 comprimidos','Tomar 1 comprimido de 8/8 h por 7–10 dias (ou 200 mg 5×/dia)'],['OU Valaciclovir 1 g (500 mg × 2) — 1º episódio','20 comprimidos de 1 g','Tomar 1 g de 12/12 h por 7–10 dias'],['Aciclovir 400 mg — RECORRÊNCIA (ter em casa)','10 comprimidos','Tomar 2 comprimidos (800 mg) de 8/8 h por 2 dias, iniciando ao primeiro sinal'],['OU Valaciclovir 500 mg — recorrência','6 comprimidos','Tomar 1 comprimido de 12/12 h por 3 dias'],['Aciclovir 400 mg — SUPRESSÃO (≥ 6 recorrências/ano, impacto psicossocial, parceiro soronegativo)','60 comprimidos','Tomar 1 comprimido de 12/12 h, diariamente, por 6–12 meses e reavaliar (ou valaciclovir 500 mg 1×/dia)'],['Dipirona 500 mg','10 comprimidos','Tomar 1 comprimido de 6/6 h se dor']]},{v:'USO TÓPICO',i:[['Lidocaína 2% gel (genital/dor) ou Vaselina/protetor labial com FPS (labial)','1 bisnaga','Aplicar nas lesões antes de urinar/4×/dia (gel); manter os lábios hidratados e protegidos do sol']]}],ori:['Lesões são contagiosas até formar crosta (7–10 dias): não beijar/compartilhar copos e toalhas (labial), abstinência sexual durante as lesões/pródromos e uso de preservativo sempre (transmissão também assintomática — 70% das transmissões)','Gatilhos: sol (protetor labial FPS), febre, estresse, menstruação, privação de sono, trauma local; lavar as mãos após tocar (risco ocular/panarício)','Manter a área limpa e seca; banho de assento morno; roupa íntima de algodão; urinar no chuveiro/com água morna se dor (genital)','Não usar corticoide tópico; antivirais tópicos têm pouca eficácia; contar ao(s) parceiro(s) — teste sorológico tipo-específico se desejado; supressão reduz transmissão em ~50%','Gestante com história de herpes genital: informar o pré-natal (supressão a partir de 36 semanas)'],al:['Olho vermelho/dor/visão embaçada ou lesões perto do olho (ceratite herpética) → oftalmo urgente','Lesões extensas/disseminadas, febre alta, confusão, cefaleia intensa, rigidez de nuca (encefalite/meningite herpética)','Incapacidade de urinar, dor intensa não controlada, desidratação (1º episódio genital grave)','Lesões que não cicatrizam em 2–3 semanas (imunossupressão/HIV, resistência) ou úlcera genital indolor com gânglios (sífilis)'],ref:'CDC STI Treatment Guidelines 2021; MS — PCDT IST 2022; Spruance 2003 (valaciclovir 1 dia); Cochrane 2015 (labial); IUSTI 2017; Febrasgo 2021 (gestante).'}
);
